DO $$ DECLARE n integer; blocked boolean:=false; BEGIN BEGIN CREATE TEMP TABLE beta_signup_validation(id integer,raw_app_meta_data jsonb) ON COMMIT DROP; CREATE TRIGGER beta_validate BEFORE INSERT ON beta_signup_validation FOR EACH ROW EXECUTE FUNCTION public.enforce_beta_google_signup_limit(); UPDATE public.beta_signup_capacity SET google_users=29 WHERE id=1; INSERT INTO beta_signup_validation VALUES(30,'{"provider":"google"}'::jsonb); SELECT google_users INTO n FROM public.beta_signup_capacity WHERE id=1; IF n IS DISTINCT FROM 30 THEN RAISE EXCEPTION 'Boundary test failed: expected 30'; END IF; BEGIN INSERT INTO beta_signup_validation VALUES(31,'{"provider":"google"}'::jsonb); EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE '%30 Google user limit%' THEN RAISE; END IF; blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'Boundary test failed: signup 31 allowed'; END IF; UPDATE beta_signup_validation SET raw_app_meta_data='{"provider":"google","signed_in":true}'::jsonb WHERE id=30; INSERT INTO beta_signup_validation VALUES(32,'{"provider":"email"}'::jsonb); SELECT google_users INTO n FROM public.beta_signup_capacity WHERE id=1; IF n IS DISTINCT FROM 30 THEN RAISE EXCEPTION 'Existing sign-in test failed'; END IF; RAISE EXCEPTION USING ERRCODE='ZX001',MESSAGE='Rollback successful beta tests'; EXCEPTION WHEN SQLSTATE 'ZX001' THEN NULL; END; END $$;